def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    my_c = my.count('C')
    my_d = n - my_c
    last_my = my[-1]
    last_opp = opp[-1]

    if opp_d == n:
        return 'D'

    if opp_d == 0:
        if my_d > 0:
            return 'D'
        if n >= 10 and n % 10 == 0:
            return 'D'
        return 'C'

    if last_my == 'D':
        if last_opp == 'C':
            if opp_d * 5 <= n:
                return 'D'
            return 'C'
        else:
            if opp_d * 2 >= n:
                return 'D'
            return 'C'
    else:
        if last_opp == 'D':
            if len(my) >= 2 and 'D' in my[-2:]:
                return 'C'
            return 'D'
        else:
            if my_c / n > 0.85 and n >= 10:
                if rng.random() < 0.3:
                    return 'D'
            return 'C'
